const http = require('http');
const WebSocket = require('ws');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const STORAGE_ROOT = path.resolve('/var/chat/encrypted_logs');
const ENCRYPTION_KEY = crypto.randomBytes(32);
const IV_LENGTH = 16;

function encrypt(text) {
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const tag = cipher.getAuthTag().toString('hex');
  return iv.toString('hex') + ':' + tag + ':' + encrypted;
}

function decrypt(encryptedText) {
  const parts = encryptedText.split(':');
  const iv = Buffer.from(parts[0], 'hex');
  const tag = Buffer.from(parts[1], 'hex');
  const encrypted = parts[2];
  const decipher = crypto.createDecipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  decipher.setAuthTag(tag);
  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

class RoomPathResolver {
  constructor(baseDir) {
    this.baseDir = baseDir;
    this.cache = new Map();
  }

  sanitizeRoomName(roomName) {
    // Remove null bytes and control characters
    let cleaned = roomName.replace(/[\x00-\x1f\x7f]/g, '');
    // Collapse multiple dots to single dot
    cleaned = cleaned.replace(/\.{2,}/g, '.');
    // Remove leading/trailing whitespace and dots
    cleaned = cleaned.replace(/^[\s.]+|[\s.]+$/g, '');
    return cleaned;
  }

  resolveLogPath(roomName) {
    const sanitized = this.sanitizeRoomName(roomName);
    if (!sanitized || sanitized.length === 0) {
      throw new Error('Invalid room name');
    }
    if (this.cache.has(sanitized)) {
      return this.cache.get(sanitized);
    }
    // Build path using path.join for proper OS handling
    const logFile = path.join(this.baseDir, sanitized, 'messages.enc');
    this.cache.set(sanitized, logFile);
    return logFile;
  }

  validateResolvedPath(resolvedPath) {
    // Ensure the resolved path starts with our base directory
    const normalized = path.normalize(resolvedPath);
    return normalized.startsWith(this.baseDir);
  }
}

const resolver = new RoomPathResolver(STORAGE_ROOT);

class ChatRoom {
  constructor(name) {
    this.name = name;
    this.clients = new Set();
    this.messageCount = 0;
  }

  async persistMessage(username, content) {
    const timestamp = new Date().toISOString();
    const logEntry = JSON.stringify({ username, content, timestamp });
    const encrypted = encrypt(logEntry);

    const logPath = resolver.resolveLogPath(this.name);
    const dir = path.dirname(logPath);

    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.appendFileSync(logPath, encrypted + '\n');
    this.messageCount++;
  }

  async getHistory(limit = 50) {
    const logPath = resolver.resolveLogPath(this.name);
    if (!fs.existsSync(logPath)) return [];

    const content = fs.readFileSync(logPath, 'utf8');
    const lines = content.trim().split('\n').slice(-limit);
    return lines.map(line => {
      try { return JSON.parse(decrypt(line)); }
      catch { return null; }
    }).filter(Boolean);
  }
}

const rooms = new Map();

function getOrCreateRoom(roomName) {
  if (!rooms.has(roomName)) {
    rooms.set(roomName, new ChatRoom(roomName));
  }
  return rooms.get(roomName);
}

const server = http.createServer((req, res) => {
  if (req.method === 'GET' && req.url.startsWith('/api/history/')) {
    const roomName = decodeURIComponent(req.url.slice('/api/history/'.length));
    try {
      const room = getOrCreateRoom(roomName);
      const logPath = resolver.resolveLogPath(roomName);
      // Validation check
      if (!resolver.validateResolvedPath(logPath)) {
        res.writeHead(403);
        res.end('Access denied');
        return;
      }
      room.getHistory().then(history => {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(history));
      });
    } catch (e) {
      res.writeHead(400);
      res.end('Invalid room');
    }
  } else {
    res.writeHead(404);
    res.end();
  }
});

const wss = new WebSocket.Server({ server });

wss.on('connection', (ws) => {
  let currentRoom = null;
  let username = null;

  ws.on('message', async (data) => {
    try {
      const msg = JSON.parse(data);

      if (msg.type === 'join') {
        username = msg.username?.replace(/[^a-zA-Z0-9_-]/g, '') || 'anon';
        const roomName = msg.room || 'general';
        currentRoom = getOrCreateRoom(roomName);
        currentRoom.clients.add(ws);
        ws.send(JSON.stringify({ type: 'joined', room: roomName }));
      }

      if (msg.type === 'chat' && currentRoom && username) {
        const content = msg.content?.substring(0, 2000) || '';
        await currentRoom.persistMessage(username, content);
        const broadcast = JSON.stringify({
          type: 'message', username, content,
          timestamp: new Date().toISOString()
        });
        currentRoom.clients.forEach(client => {
          if (client.readyState === WebSocket.OPEN) client.send(broadcast);
        });
      }
    } catch (e) { /* ignore malformed messages */ }
  });

  ws.on('close', () => {
    if (currentRoom) currentRoom.clients.delete(ws);
  });
});

server.listen(3000, () => console.log('Chat server on :3000'));
